<ellipse class="eye" cx="34" cy="41" rx="4" ry="5.5"/><ellipse class="eye" cx="47" cy="41" rx="4" ry="5.5"/><circle class="shine" cx="35" cy="39" r="1.6"/><circle class="shine" cx="48" cy="39" r="1.6"/><ellipse class="cheek" cx="27" cy="48" rx="4" ry="2.5"/><ellipse class="cheek" cx="54" cy="48" rx="4" ry="2.5"/><path d="M34 32l6 2m4 0l7-3" fill="none" stroke="#4e3028" stroke-width="2.5"/><path d="M37 51q5-3 10 0l-1 5h-8z" fill="white" stroke="#8d483d" stroke-width="1.5"/>
</g><path d="M34 66q9 4 19-1" fill="none" stroke="#fff8" stroke-width="2"/>
</svg></div></div></div></div></section><section class="panel r"><div class="kc-qtime" id="clockRed"></div><div class="q" id="qRed"></div><div class="opts" id="oRed"></div></section></div><div class="credit">Hệ Sinh Thái Quản lý Nhà Trường - Thiết kế bởi thầy giáo Nguyễn Hồng Dân -</div></div><div class="win-effects" id="winEffects" aria-hidden="true"></div>
<div class="overlay" id="overlay"><div class="modal"><h2 id="winTitle">Kết thúc</h2><p id="winText"></p><button class="btn" id="again" type="button">Chơi lại</button></div></div><div class="overlay" id="importOverlay"><div class="modal"><h2>Nhập ngân hàng định dạng cũ</h2><p>Dán mỗi dòng theo mẫu: <code>Câu hỏi | A | B | C | D | đáp án 1-4</code>.</p><textarea class="import-area" id="importText"></textarea><div class="modal-actions"><button class="btn light" id="cancelImport" type="button">Hủy</button><button class="btn primary" id="confirmImport" type="button">Nhập câu hỏi</button></div></div></div>
<script>
const API='<?= e($base) ?>hoclieu_game_keoco_api.php', CSRF='<?= e($_SESSION['keoco_question_bank_csrf']) ?>';
const DEFAULT=`Thủ đô của Việt Nam là thành phố nào? | Hà Nội | Huế | TP. Hồ Chí Minh | Đà Nẵng | 1
Một kilômét bằng bao nhiêu mét? | 100 | 1000 | 10 | 10000 | 2
Phương trình 2x + 6 = 0 có nghiệm là? | x = 6 | x = 3 | x = -3 | x = -6 | 3
1 giờ có bao nhiêu phút? | 30 | 60 | 90 | 100 | 2
Hình nào có 3 cạnh? | Vuông | Tròn | Tam giác | Chữ nhật | 3
Năm 1945 gắn với sự kiện nào? | Đổi mới | Cách mạng tháng Tám | Điện Biên Phủ | Thống nhất | 2
Kết quả 7 x 8 là? | 54 | 56 | 64 | 48 | 2
Hành tinh chúng ta đang sống tên gì? | Sao Hỏa | Mặt Trăng | Trái Đất | Sao Kim | 3`;
let currentSetId=null, canEdit=true, bank=[],blue=0,red=0,tLeft=180,tick=null,mute=false,mode='split',winBy=5,loopQ=true,usedB=[],usedR=[],curB=null,curR=null,lockB=false,lockR=false,names={blue:'Đội Xanh',red:'Đội Đỏ'},audioCtx=null,bgTimer=null,bgStep=0,directionTimer=null,gameOver=false;
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function parseBank(text){return text.split(/\n+/).map(line=>{const p=line.split('|').map(s=>s.trim());return p.length>=6&&p[0]&&p.slice(1,5).every(Boolean)?{question_text:p[0],option_a:p[1],option_b:p[2],option_c:p[3],option_d:p[4],correct_option:Math.max(1,Math.min(4,parseInt(p[5],10)||1))}:null}).filter(Boolean)}
function card(q={question_text:'',option_a:'',option_b:'',option_c:'',option_d:'',correct_option:1}){const el=document.createElement('article');el.className='question-card';el.innerHTML=`<div class="question-head"><strong>Câu hỏi</strong><div class="question-actions"><button type="button" class="btn light small duplicate">Nhân bản</button><button type="button" class="btn danger small remove">Xóa</button></div></div><div class="question-grid"><label class="prompt">Nội dung<textarea class="question_text" rows="2">${esc(q.question_text)}</textarea></label><label>A<input class="option_a" value="${esc(q.option_a)}"></label><label>B<input class="option_b" value="${esc(q.option_b)}"></label><label>C<input class="option_c" value="${esc(q.option_c)}"></label><label>D<input class="option_d" value="${esc(q.option_d)}"></label><label>Đáp án đúng<select class="correct_option"><option value="1">A</option><option value="2">B</option><option value="3">C</option><option value="4">D</option></select></label></div>`;el.querySelector('.correct_option').value=q.correct_option||1;el.querySelector('.remove').onclick=()=>{el.remove();updateEmpty()};el.querySelector('.duplicate').onclick=()=>{const copy=readCard(el);el.after(card(copy));updateEmpty()};return el}
function renderQuestions(rows){$('questionList').innerHTML='';rows.forEach(q=>$('questionList').append(card(q)));updateEmpty()}
function updateEmpty(){$('questionList').querySelector('.empty')?.remove();if(!$('questionList').children.length){const e=document.createElement('div');e.className='empty';e.textContent='Chưa có câu hỏi. Hãy thêm câu hỏi hoặc nhập định dạng cũ.';$('questionList').append(e)}}
function readCard(el){let q={};['question_text','option_a','option_b','option_c','option_d','correct_option'].forEach(k=>q[k]=el.querySelector('.'+k).value.trim());q.correct_option=Number(q.correct_option);return q}
function questionRows(){return [...$('questionList').querySelectorAll('.question-card')].map(readCard)}
function editorState(edit){['setTitle','setShared','addQuestion','saveBtn','importBtn'].forEach(id=>$(id).disabled=!edit);$('questionList').querySelectorAll('input,textarea,select,button').forEach(el=>el.disabled=!edit)}
async function request(action,data={},method='POST'){const o=method==='GET'?{headers:{Accept:'application/json'}}:{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({action,csrf:CSRF,...data})};const res=await fetch(method==='GET'?API+'?action='+encodeURIComponent(action)+(data.id?'&id='+encodeURIComponent(data.id):''):API,o);const json=await res.json().catch(()=>({}));if(!res.ok||!json.ok)throw Error(json.message||'Không thể xử lý yêu cầu.');return json}
function status(s){$('bankStatus').textContent=s}
async function refreshSets(){try{const d=await request('list',{},'GET'),selected=String(currentSetId||'');$('setList').innerHTML='<option value="">Bộ câu hỏi mới (chưa lưu)</option>'+d.sets.map(s=>`<option value="${s.id}">${esc(s.title)} (${s.question_count} câu)${s.is_shared?' · dùng chung':''}${s.can_edit?'':''}</option>`).join('');$('setList').value=selected;status(d.sets.length?'':'Chưa có bộ nào đã lưu.')}catch(e){status(e.message)}}
function resetSet(){currentSetId=null;canEdit=true;$('setList').value='';$('setTitle').value='';$('setShared').checked=false;$('deleteBtn').hidden=true;renderQuestions(parseBank(DEFAULT));editorState(true);status('Bộ câu hỏi mới')}
async function loadSet(){const id=$('setList').value;if(!id)return resetSet();try{const d=await request('get',{id},'GET');currentSetId=d.set.id;canEdit=d.set.can_edit;$('setTitle').value=d.set.title;$('setShared').checked=d.set.is_shared;$('deleteBtn').hidden=!canEdit;renderQuestions(d.questions);editorState(canEdit);status(canEdit?'Đã tải bộ câu hỏi.':'Bộ câu hỏi dùng chung (chỉ xem).')}catch(e){status(e.message)}}
$('addQuestion').onclick=()=>{$('questionList').querySelector('.empty')?.remove();$('questionList').append(card());};$('newBtn').onclick=resetSet;$('loadBtn').onclick=loadSet;$('setList').onchange=loadSet;
$('importBtn').onclick=()=>{$('importText').value='';$('importOverlay').classList.add('show')};$('cancelImport').onclick=()=>$('importOverlay').classList.remove('show');$('confirmImport').onclick=()=>{const rows=parseBank($('importText').value);if(!rows.length)return alert('Không tìm thấy dòng đúng định dạng.');renderQuestions(rows);$('importOverlay').classList.remove('show');status('Đã nhập '+rows.length+' câu hỏi; bấm Lưu ngân hàng để lưu lại.')};
$('saveBtn').onclick=async()=>{const title=$('setTitle').value.trim(),questions=questionRows();if(!title)return alert('Hãy nhập tên bộ câu hỏi.');if(!questions.length)return alert('Hãy thêm ít nhất một câu hỏi.');try{status('Đang lưu...');const d=await request('save',{id:currentSetId,title,is_shared:$('setShared').checked,questions});currentSetId=d.id;await refreshSets();$('setList').value=String(currentSetId);$('deleteBtn').hidden=false;status(d.message)}catch(e){status(e.message)}};
$('deleteBtn').onclick=async()=>{if(!currentSetId||!confirm('Xóa vĩnh viễn bộ câu hỏi này?'))return;try{await request('delete',{id:currentSetId});currentSetId=null;await refreshSets();resetSet()}catch(e){status(e.message)}};
function audio(){if(!audioCtx)audioCtx=new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();return audioCtx}function tone(freq,seconds=.2,volume=.04,type='triangle'){const ctx=audio(),o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+seconds);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+seconds+.03)}function sound(ok){if(!mute)tone(ok?660:180,.18,.08)}function playMusic(){if(mute)return;const melody=[523.25,659.25,783.99,659.25,587.33,698.46,880,698.46,659.25,783.99,1046.5,783.99,698.46,587.33,523.25,0];const note=melody[bgStep++%melody.length];if(note){tone(note,.25,.035,'sine');if(bgStep%4===1)tone(note/2,.32,.018,'triangle')}}function startMusic(){if(mute||bgTimer)return;audio();playMusic();bgTimer=setInterval(playMusic,300)}function stopMusic(){if(bgTimer){clearInterval(bgTimer);bgTimer=null}}
function pick(side){const used=side==='b'?usedB:usedR;let pool=bank.map((_,i)=>i).filter(i=>!used.includes(i));if(!pool.length){if(!loopQ)return null;if(side==='b')usedB=[];else usedR=[];pool=bank.map((_,i)=>i)}const i=pool[Math.floor(Math.random()*pool.length)];if(side==='b')usedB.push(i);else usedR.push(i);return bank[i]}
function renderMath(el){if(window.renderMathInElement)renderMathInElement(el,{delimiters:[{left:'$',right:'$',display:false},{left:'\\(',right:'\\)',display:false}]})}
function drawSide(side,item){const q=$(side==='b'?'qBlue':'qRed'),box=$(side==='b'?'oBlue':'oRed');if(!item){q.textContent='Hết câu hỏi';box.innerHTML='';return}q.textContent=item.q;renderMath(q);box.innerHTML='';item.opts.forEach((opt,idx)=>{const b=document.createElement('button');b.textContent=opt;b.onclick=()=>answer(side,idx,item,b,box);box.append(b);renderMath(b)})}
function resetVictoryEffects(){$('teamBlue').classList.remove('victorious','defeated');$('teamRed').classList.remove('victorious','defeated');$('winEffects').replaceChildren()}
function celebrate(winner){const winnerTeam=$(winner==='blue'?'teamBlue':'teamRed'),loserTeam=$(winner==='blue'?'teamRed':'teamBlue'),colors=winner==='blue'?['#1769d1','#60a5fa','#bfdbfe','#f8fafc']:['#d93445','#fb7185','#fecdd3','#fff1f2'];winnerTeam.classList.add('victorious');loserTeam.classList.add('defeated');const effects=$('winEffects');for(let i=0;i<96;i++){const piece=document.createElement('i');piece.className='confetti';piece.style.cssText=`left:${Math.random()*100}vw;--confetti-color:${colors[i%colors.length]};--drift:${Math.round((Math.random()-.5)*42)}vw;--spin:${Math.round(540+Math.random()*1080)}deg;--fall-duration:${(2.3+Math.random()*1.7).toFixed(2)}s;--fall-delay:${(Math.random()*.8).toFixed(2)}s`;effects.append(piece)}}
function shiftRope(side=null){const diff=red-blue,offset=Math.max(-1,Math.min(1,diff/winBy))*document.querySelector(".mid").clientWidth*.08;$('rope').style.transform='translate(calc(-50% + '+offset+'px),-50%)';$('sBlue').textContent=names.blue+' '+blue;$('sRed').textContent=red+' '+names.red;const rope=$('rope'),direction=$('direction');rope.classList.remove('pulling','right');void rope.offsetWidth;if(side){rope.classList.add('pulling');if(side==='r')rope.classList.add('right');direction.className='direction '+(side==='b'?'left':'right')+' show';direction.textContent=side==='b'?'← XANH KÉO!':'ĐỎ KÉO! →';clearTimeout(directionTimer);directionTimer=setTimeout(()=>direction.classList.remove('show'),650)}if(Math.abs(blue-red)>=winBy)endGame(blue>red?'blue':'red')}
function nextShared(){const item=pick('b');curB=curR=item;lockB=lockR=false;drawSide('b',item);drawSide('r',item)}
function answer(side,idx,item,btn,box){if((side==='b'&&lockB)||(side==='r'&&lockR)||!item)return;const ok=idx===item.ans;sound(ok);[...box.children].forEach((el,i)=>{el.disabled=true;if(i===item.ans)el.classList.add('ok')});if(!ok)btn.classList.add('bad');if(ok){if(side==='b')blue++;else red++}shiftRope(ok?side:null);if($('overlay').classList.contains('show'))return;if(mode==='shared'){lockB=lockR=true;setTimeout(nextShared,700)}else if(side==='b'){lockB=true;setTimeout(()=>{curB=pick('b');lockB=false;drawSide('b',curB)},650)}else{lockR=true;setTimeout(()=>{curR=pick('r');lockR=false;drawSide('r',curR)},650)}}
function fmt(s){return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}function endGame(winner=null){if(gameOver)return;gameOver=true;clearInterval(tick);stopMusic();if(winner)celebrate(winner);$('winTitle').textContent=winner?names[winner]+' thắng!':'Hết giờ';$('winText').textContent=names.blue+' '+blue+' – '+red+' '+names.red;$('overlay').classList.add('show')}
function start(){const rows=questionRows();if(rows.length<4)return alert('Cần ít nhất 4 câu hỏi.');if(rows.some(q=>!q.question_text||!q.option_a||!q.option_b||!q.option_c||!q.option_d))return alert('Mỗi câu hỏi phải có nội dung và đủ 4 đáp án.');resetVictoryEffects();gameOver=false;bank=rows.map(q=>({q:q.question_text,opts:[q.option_a,q.option_b,q.option_c,q.option_d],ans:q.correct_option-1}));names.blue=$('nBlue').value||'Đội Xanh';names.red=$('nRed').value||'Đội Đỏ';mode=$('mode').value;winBy=Math.max(2,Number($('winBy').value)||5);loopQ=$('loopQ').value==='1';blue=red=0;usedB=[];usedR=[];tLeft=Math.max(1,Number($('mins').value)||3)*60;$('setup').hidden=true;$('play').hidden=false;$('timer').textContent=fmt(tLeft);shiftRope();startMusic();if(mode==='shared')nextShared();else{curB=pick('b');curR=pick('r');drawSide('b',curB);drawSide('r',curR)}clearInterval(tick);tick=setInterval(()=>{tLeft--;$('timer').textContent=fmt(Math.max(0,tLeft));if(tLeft<=0)endGame(blue===red?null:(blue>red?'blue':'red'))},1000)}
$('startBtn').onclick=start;$('muteBtn').onclick=function(){mute=!mute;this.textContent=mute?'Bật nhạc':'Tắt nhạc';if(mute)stopMusic();else startMusic()};$('fullBtn').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();$('exitBtn').onclick=()=>{clearInterval(tick);stopMusic();location.href='<?= e($base) ?>hoclieu.php?tab=games'};$('again').onclick=()=>{resetVictoryEffects();$('overlay').classList.remove('show');$('play').hidden=true;$('setup').hidden=false};renderQuestions(parseBank(DEFAULT));refreshSets();
</script><script src="<?= e($base) ?>assets/cds-keoco-display.js?v=20261109-4"></script><script src="<?= e($base) ?>assets/cds-keoco-upgrade.js?v=20261110-1"></script><script src="<?= e($base) ?>assets/cds-keoco-sound.js?v=20261109-4"></script><script src="<?= e($base) ?>assets/cds-keoco-scene.js?v=20261109-4"></script><script src="<?= e($base) ?>assets/cds-keoco-rope.js?v=20261109-4"></script><script src="<?= e($base) ?>assets/cds-keoco-finale.js?v=20261109-4"></script><?php require __DIR__ . '/includes/game_credit.php'; ?></body></html>
